          name = "Effect",
          summary = "Different types of Source effects.",
          description = "Different types of effects that can be applied with `Source:setEffectEnabled`.",
          key = "Effect",
          module = "lovr.audio",
          notes = "The active spatializer will determine which effects are supported.  If an unsupported effect is enabled on a Source, no error will be reported.  Instead, it will be silently ignored.\n\nSee `lovr.audio.getSpatializer` for a table of the supported effects for each spatializer.",
          values = {
            {
              name = "absorption",
              description = "Models absorption as sound travels through the air, water, etc."
            },
            {
              name = "attenuation",
              description = "Decreases audio volume with distance (1 / max(distance, 1))."
            },
            {
              name = "occlusion",
              description = "Causes audio to drop off when the Source is occluded by geometry."
            },
            {
              name = "reverb",
              description = "Models reverb caused by audio bouncing off of geometry."
            },
            {
              name = "spatialization",
              description = "Spatializes the Source using either simple panning or an HRTF."
            },
            {
              name = "transmission",
              description = "Causes audio to be heard through walls when occluded, based on audio materials."
            }
          }
        },
        {
          name = "ReverbMode",
          summary = "Different ways of simulating reverb.",
          description = "This controls the method used to simulate reverb on a `Source`.\n\nNote that there is also `ReverbType` set in `lovr.conf`, which can be changed independently of the reverb mode used by a source.",
          key = "ReverbMode",
          module = "lovr.audio",
          related = {
            "ReverbType",
            "Source:setReverb",
            "lovr.conf"
          },
          values = {
            {
              name = "listener",
              description = "The listener will cast rays outwards to compute the reverb characteristics of the room, and use this to apply reverb to all sources using the `listener` reverb mode.  This is less expensive than per-source reverb because the reverb only needs to be simulated once, but it can be lower quality."
            },
            {
              name = "source",
              description = "When a Source has this reverb mode, it will compute its own reverb independently.  This will give higher quality results, but it can quickly become very expensive to compute reverb for large numbers of sources.  Consider enabling this only for a small number of important sounds."
            }
          }
        },
