        {
          name = "MeshStorage",
          summary = "Whether a Mesh stores its data on the CPU or GPU.",
          description = "Whether a Mesh stores its data on the CPU or GPU.",
          key = "MeshStorage",
          module = "lovr.graphics",
          notes = "There are some significant differences and tradeoffs between the two modes:\n\n- CPU meshes store a second copy of the vertices in RAM, which can be expensive for large\n  meshes.\n- When vertices are modified, CPU meshes will update the CPU copy, and only upload to the GPU\n  the next time the Mesh is drawn.  GPU meshes, on the other hand, will immediately upload\n  modified vertices to the GPU.  This means that calling `Mesh:setVertices` multiple times per\n  frame will be faster with a CPU mesh.\n- CPU meshes have an internal vertex buffer that can't be accessed from Lua.\n- CPU meshes can compute their bounding box using `Mesh:computeBoundingBox`.  GPU meshes can't.",
          related = {
            "lovr.graphics.newMesh"
          },
          values = {
            {
              name = "cpu",
              description = "The Mesh will store a copy of the vertices on the CPU."
            },
            {
              name = "gpu",
              description = "The Mesh will not keep a CPU copy, only storing vertices on the GPU."
            }
          }
        },
        {
          name = "OriginType",
          summary = "Different coordinate spaces for nodes in a Model.",
          description = "Different coordinate spaces for nodes in a `Model`.",
          key = "OriginType",
          module = "lovr.graphics",
          related = {
            "Model:getNodePosition",
            "Model:getNodeOrientation",
            "Model:getNodeScale",
            "Model:getNodePose",
            "Model:getNodeTransform",
            "Model:getRootNode",
            "Model:getNodeParent"
          },
          values = {
            {
              name = "root",
              description = "Transforms are relative to the origin (root) of the Model."
            },
            {
              name = "parent",
              description = "Transforms are relative to the parent of the node."
            }
          }
        },
        {
          name = "ProjectionType",
          summary = "Different projection types.",
          description = "The different projection types for `Pass:setProjection`.",
          key = "ProjectionType",
          module = "lovr.graphics",
          notes = "LÖVR creates projection matrices compatible with Vulkan.  The NDC direction is Y down, and the Z coordinate is from 0 to 1.\n\nWhen the far clipping plane is zero, LÖVR sets an infinite far plane and reverses the Z direction.  This is the default because it improves depth precision and reduces Z fighting. Using a non-infinite far plane requires the depth buffer to be cleared to 1.0 instead of 0.0 and the default depth test to be changed to `lequal` instead of `gequal`.",
          values = {
            {
              name = "orthographic",
              description = "A 2D orthographic projection given by 6 numbers: left, right, bottom, top, near, far. Left/right default to 0 and the width of the canvas.  Bottom/top default to 0 and the height of the canvas.  Near and far default to -1 and 1.  All of the numbers can be left off to set an orthographic projection with 0,0 in the upper-left corner and units in pixels."
            },
            {
              name = "perspective",
              description = "A 3D perspective projection given by 4 numbers: fovy, aspect, near, far.  Fovy is in radians and defaults to 90 degrees.  The aspect ratio is width/height and defaults to the aspect ratio of the canvas.  Near and far default to .01 and 0."
            },
            {
              name = "asymmetric",
              description = "An asymmetric perspective projection given by 6 numbers: left, right, up, down, near, far. This is meant to be used with `lovr.headset.getViewAngles`.  All of the angles are in radians, and are usually positive.  Near and far default to .01 and 0."
            },
            {
              name = "matrix",
              description = "16 numbers for a raw projection matrix, in column-major order."
            }
          }
        },
        {
          name = "ShaderFlag",
          summary = "Built-in Shader flags.",
          description = "Built-in shader flags.  Shaders can use both user-created specialization constants (or simply \"flags\") alongside the following built-in ones.",
          key = "ShaderFlag",
          module = "lovr.graphics",
          notes = "The types and default values for the flags are:\n\n<table>\n  <thead>\n    <tr>\n      <td>Flag</td>\n      <td>Type</td>\n      <td>Default</td>\n    </tr>\n  </thead>\n  <tbody>\n    <tr>\n      <td><code>pointSize</code></td>\n      <td><code>float</code></td>\n      <td><code>1.0</code></td>\n    </tr>\n    <tr>\n      <td><code>passColor</code></td>\n      <td><code>boolean</code></td>\n      <td><code>true</code></td>\n    </tr>\n    <tr>\n      <td><code>materialColor</code></td>\n      <td><code>boolean</code></td>\n      <td><code>true</code></td>\n    </tr>\n    <tr>\n      <td><code>vertexColors</code></td>\n      <td><code>boolean</code></td>\n      <td><code>true</code></td>\n    </tr>\n    <tr>\n      <td><code>uvTransform</code></td>\n      <td><code>boolean</code></td>\n      <td><code>true</code></td>\n    </tr>\n    <tr>\n      <td><code>alphaCutoff</code></td>\n      <td><code>boolean</code></td>\n      <td><code>false</code></td>\n    </tr>\n    <tr>\n      <td><code>glow</code></td>\n      <td><code>boolean</code></td>\n      <td><code>false</code></td>\n    </tr>\n    <tr>\n      <td><code>normalMap</code></td>\n      <td><code>boolean</code></td>\n      <td><code>false</code></td>\n    </tr>\n    <tr>\n      <td><code>vertexTangents</code></td>\n      <td><code>boolean</code></td>\n      <td><code>true</code></td>\n    </tr>\n    <tr>\n      <td><code>colorTexture</code></td>\n      <td><code>boolean</code></td>\n      <td><code>true</code></td>\n    </tr>\n    <tr>\n      <td><code>glowTexture</code></td>\n      <td><code>boolean</code></td>\n      <td><code>true</code></td>\n    </tr>\n    <tr>\n      <td><code>metalnessTexture</code></td>\n      <td><code>boolean</code></td>\n      <td><code>true</code></td>\n    </tr>\n    <tr>\n      <td><code>roughnessTexture</code></td>\n      <td><code>boolean</code></td>\n      <td><code>true</code></td>\n    </tr>\n    <tr>\n      <td><code>ambientOcclusion</code></td>\n      <td><code>boolean</code></td>\n      <td><code>true</code></td>\n    </tr>\n    <tr>\n      <td><code>clearcoatTexture</code></td>\n      <td><code>boolean</code></td>\n      <td><code>false</code></td>\n    </tr>\n    <tr>\n      <td><code>tonemap</code></td>\n      <td><code>boolean</code></td>\n      <td><code>false</code></td>\n    </tr>\n  </tbody> </table>",
          related = {
            "lovr.graphics.newShader",
            "Shader:clone"
          },
          values = {
            {
              name = "pointSize",
              description = "The point size when drawing points with e.g. `Pass:points`, in pixels."
            },
            {
              name = "passColor",
              description = "Multiply the pass color (`Pass:setColor`) into the `Color` variable sent to the fragment shader."
            },
            {
              name = "materialColor",
              description = "Multiply the material color (`Pass:setMaterial`) into the `Color` variable sent to the fragment shader."
            },
            {
              name = "vertexColors",
              description = "Multiply the vertex color (from the `VertexColor` attribute) into the `Color` variable sent to the fragment shader."
            },
            {
              name = "uvTransform",
              description = "Apply the UV transform from the material to the `VertexUV` attribute."
            },
            {
              name = "alphaCutoff",
              description = "Enable alpha cutoff.  When enabled, pixels will be discarded if their alpha is less than the `alphaCutoff` value of the material."
            },
            {
              name = "glow",
              description = "Enable glow.  When enabled, the Material\\'s `glowTexture` and `glow` property will get added to the color of the pixel returned by `lovrmain`.  This is also called an \"emissive\" texture and is used for parts of an object that give off light, like an LED screen or the headlights on a car."
            },
            {
              name = "normalMap",
              description = "Use the normal map texture in the material to affect the normal direction of surfaces.  This only affects the `normal` variable in the `Surface` struct."
            },
            {
              name = "vertexTangents",
              description = "Use the vertex tangents of the model for normal mapping.  When this is `false`, tangents will be computed in the fragment shader from the vertex positions, UVs, and normal vector."
            },
            {
              name = "colorTexture",
              description = "Use the color texture of the material.  If this is `false`, the color will only be derived from the `Color` variable (pass color, material color, vertex color), and the color texture will be ignored."
            },
            {
              name = "glowTexture",
              description = "Sample the `glowTexture` of the material when applying glow.  Note that glow is only active when the `glow` flag is also enabled.  If this is false, then materials will give off a constant glow using their `glow` property, and the glow texture is ignored."
            },
            {
              name = "metalnessTexture",
              description = "Sample the blue channel of the material's metalness texture when computing the metalness value of a `Surface`. When false, the surface will have a constant metalness based on the material's `metalness` property, instead of using a texture."
            },
            {
              name = "roughnessTexture",
              description = "Sample the green channel of the material's roughness texture when computing the roughness value of a `Surface`. When false, the surface will have a constant roughness based on the material's `roughness` property, instead of using a texture."
            },
            {
              name = "ambientOcclusion",
              description = "Sample the red channel of the `occlusionTexture` of the material to compute the occlusion property of a `Surface`.  When false, the occlusion will be `1.0` (no occlusion)."
            },
            {
              name = "clearcoatTexture",
              description = "Sample the red channel of the material's `clearcoatTexture` to compute the `clearcoat` property of a `Surface`.  When false, only the `clearcoat` property of the material will be used, and the texture will be ignored."
            },
            {
              name = "tonemap",
              description = "Apply ACES tonemapping to the final color output.  This will compress color channel values down to the 0-1 range while attempting to preserve detail in highlights and shadows."
            }
          }
        },
