                      type = "number?",
                      description = "The index of the first value in the Buffer to update.",
                      default = "1"
                    },
                    {
                      name = "sourceIndex",
                      type = "number?",
                      description = "The index in the table to copy from.",
                      default = "1"
                    },
                    {
